import WelcomeStorageKeys from '../constants/storage-keys';

/**
 * Generates the storage key for tracking the dismissed state of the welcome page.
 * The key is generated by replacing the `{{productName}}` placeholder in the `WelcomeStorageKeys.DISMISSED`
 * template with the lowercase version of the provided product name.
 * @param productName
 * @returns {string} The storage key for tracking the welcome page dismissed state.
 */
export default function getWelcomeDismissedStorageKey(productName: string): string {
  return WelcomeStorageKeys.DISMISSED.replace('{{productName}}', productName.toLowerCase());
}
